import { MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, smoothstep, uv, vec3 } from 'three/tsl';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, BoxGeometry } = THREE;

  const root = new Group();
  root.name = 'journal-title';
  root.userData.handlers = {};

  const ownedGeometries = [];
  const ownedMaterials = [];
  const ownedTextures = [];
  const primitiveResults = [];

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial({
    depthWrite: false,
    toneMapped: false
  });

  const gradientT = smoothstep(0.0, 1.0, uv().y);
  backdropMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    mix(
      vec3(0.086, 0.086, 0.114),
      vec3(0.906, 0.925, 0.949),
      smoothstep(0.56, 1.0, gradientT)
    ),
    gradientT
  );

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.name = 'engineered-gradient-backdrop';
  backdrop.position.set(0, -3, -2.5);
  backdrop.renderOrder = -10;
  root.add(backdrop);

  ownedGeometries.push(backdropGeometry);
  ownedMaterials.push(backdropMaterial);

  const accentGeometry = new BoxGeometry(0.08, 0.72, 0.035);
  const accentMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38',
    toneMapped: false
  });
  const accent = new Mesh(accentGeometry, accentMaterial);
  accent.name = 'signal-red-accent';
  accent.position.set(-1.55, 0.02, 0.18);
  root.add(accent);

  ownedGeometries.push(accentGeometry);
  ownedMaterials.push(accentMaterial);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let textOffset = 0;

  for (const item of items) {
    const content = typeof item?.text === 'string' ? item.text : '';
    if (!content) continue;

    const textObject = ctx.fontAtlas.createText(content, {
      fontSize: item.typography?.fontSize ?? 96,
      color: '#e8ecf2',
      align: 'center',
      maxWidthPx: 900,
      letterSpacingPx: 1
    });

    textObject.name = item.role || 'headline';
    textObject.position.set(0, textOffset, 0.22);
    root.add(textObject);
    textOffset -= 0.42;
  }

  const spriteGeometry = new PlaneGeometry(2.15, 1.34375);
  const spriteMaterial = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.92,
    depthWrite: false,
    toneMapped: false
  });
  const sprite = new Mesh(spriteGeometry, spriteMaterial);
  sprite.name = 'floating-accent-sprite';
  sprite.position.set(1.42, -0.82, 0.12);
  sprite.rotation.z = -0.08;
  sprite.renderOrder = 2;
  root.add(sprite);

  ownedGeometries.push(spriteGeometry);
  ownedMaterials.push(spriteMaterial);

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (!root.parent && root.userData.cleaned) {
        texture.dispose?.();
        return;
      }

      const source = config.atlasRegion ?? {
        x: 0,
        y: 0,
        width: 512,
        height: 320
      };

      const image = texture.image;
      const atlasWidth = image?.width || source.width;
      const atlasHeight = image?.height || source.height;

      texture.wrapS = THREE.ClampToEdgeWrapping;
      texture.wrapT = THREE.ClampToEdgeWrapping;
      texture.repeat.set(
        source.width / atlasWidth,
        source.height / atlasHeight
      );
      texture.offset.set(
        source.x / atlasWidth,
        1 - (source.y + source.height) / atlasHeight
      );

      if ('colorSpace' in texture && THREE.SRGBColorSpace) {
        texture.colorSpace = THREE.SRGBColorSpace;
      }

      spriteMaterial.map = texture;
      spriteMaterial.needsUpdate = true;
      ownedTextures.push(texture);
    }).catch(() => {});
  }

  sprite.onBeforeRender = (_renderer, _scene, camera) => {
    if (camera) sprite.quaternion.copy(camera.quaternion);
  };

  for (const primitive of config.cinematicPrimitives ?? []) {
    const handler = ctx.primitives?.[primitive.name];
    if (typeof handler === 'function') {
      const result = handler(root, primitive.params);
      if (result) primitiveResults.push(result);
    }
  }

  root.userData.cleanup = () => {
    if (root.userData.cleaned) return;
    root.userData.cleaned = true;

    for (const result of primitiveResults) {
      result?.timeline?.kill?.();
      result?.cleanup?.();
    }

    sprite.onBeforeRender = null;

    for (const material of ownedMaterials) {
      material.dispose?.();
    }

    for (const geometry of ownedGeometries) {
      geometry.dispose?.();
    }

    for (const texture of ownedTextures) {
      texture.dispose?.();
    }

    root.clear();
  };

  return root;
}
